// EComm — standalone scene 5 (Scene5Manual). Transparent background, no scene-level
// fade in/out. Content animates in via its own springs; <Background/> + SceneWrap removed.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "monospace";


const Scene5Manual: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Phase 1: listings pulling location by location (0 -> ~110f)
  // Phase 2: calendar with zip codes (~110 -> end)
  // S4 dur = 215f
  // Transcript:
  // line 9-10 (manual pull location by location): 13.6 - 18.0s -> in scene local: 15-125
  // line 11-12 (only 1 zip on 1 day): 18.0 - 21.6s -> in scene local: 125-215

  const phase1Out = interpolate(
    frame,
    [105, 125],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const phase2In = interpolate(
    frame,
    [120, 145],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cardIn = springIn(frame, vfps, 4, "LIQUID");
  const driftY = ambientDrift(frame, 2, 110, "manual");

  // 10 locations pulling
  const locations = Array.from({ length: 10 }, (_, i) => i);
  // Each location row "pulls" at different frame
  const pullStart = 15;
  const pullStep = 9;

  // Phase 2 — calendar (1 week, 7 days, each w/ NY zip)
  const zips = ["10001", "10011", "10024", "10128", "10003", "11201", "11215"];
  const dayNames = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  return (
    <AbsoluteFill>
      {null}

      {/* Phase 1: Dashboard with pulling listings */}
      <AbsoluteFill
        style={{
          opacity: phase1Out * cardIn,
          padding: base * 0.07,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            width: width * 0.55,
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.032,
            boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
          }}
        >
          {/* Header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.014,
              marginBottom: base * 0.022,
              paddingBottom: base * 0.016,
              borderBottom: `1px solid ${COLORS.border}`,
            }}
          >
            <div
              style={{
                width: base * 0.018,
                height: base * 0.018,
                borderRadius: "50%",
                background: COLORS.orange,
              }}
            />
            <div
              style={{
                width: base * 0.16,
                height: base * 0.012,
                background: "rgba(255,255,255,0.2)",
                borderRadius: 3,
              }}
            />
            <div style={{ flex: 1 }} />
            <div
              style={{
                fontFamily: FONT_MONO,
                fontSize: base * 0.013,
                color: COLORS.textSubtle,
                letterSpacing: "0.05em",
              }}
            >
              {Math.min(
                10,
                Math.max(0, Math.floor((frame - pullStart) / pullStep) + 1)
              )}{" "}
              / 10
            </div>
          </div>

          {/* Location rows */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: base * 0.008,
            }}
          >
            {locations.map((i) => {
              const rowStart = pullStart + i * pullStep;
              const pullProgress = interpolate(
                frame,
                [rowStart, rowStart + 10],
                [0, 1],
                {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }
              );
              const rowOp = interpolate(pullProgress, [0, 0.3], [0.3, 1]);
              const barFill = pullProgress;

              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: base * 0.012,
                    padding: `${base * 0.008}px ${base * 0.012}px`,
                    background: "rgba(255,255,255,0.03)",
                    borderRadius: base * 0.006,
                    opacity: rowOp,
                  }}
                >
                  {/* Location icon */}
                  <svg
                    width={base * 0.014}
                    height={base * 0.014}
                    viewBox="0 0 24 24"
                  >
                    <path
                      d="M12 2 C8 2 5 5 5 9 C5 14 12 22 12 22 C12 22 19 14 19 9 C19 5 16 2 12 2 Z"
                      fill={COLORS.orange}
                    />
                    <circle cx="12" cy="9" r="2.5" fill={COLORS.card} />
                  </svg>
                  {/* Location label */}
                  <div
                    style={{
                      fontFamily: FONT_MONO,
                      fontSize: base * 0.011,
                      color: COLORS.textMuted,
                      width: base * 0.08,
                    }}
                  >
                    LOC-{String(i + 1).padStart(2, "0")}
                  </div>
                  {/* Progress bar */}
                  <div
                    style={{
                      flex: 1,
                      height: base * 0.008,
                      background: "rgba(255,255,255,0.08)",
                      borderRadius: 3,
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        width: `${barFill * 100}%`,
                        height: "100%",
                        background: COLORS.orange,
                        borderRadius: 3,
                      }}
                    />
                  </div>
                  {/* Status */}
                  <div
                    style={{
                      width: base * 0.018,
                      height: base * 0.018,
                      borderRadius: "50%",
                      background:
                        barFill > 0.95
                          ? COLORS.orange
                          : "rgba(255,255,255,0.15)",
                      opacity: barFill > 0.95 ? 1 : 0.5,
                    }}
                  />
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>

      {/* Phase 2: Calendar with zip codes */}
      <AbsoluteFill
        style={{
          opacity: phase2In,
          padding: base * 0.08,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: base * 0.035,
            boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
            width: width * 0.6,
          }}
        >
          {/* Calendar header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.014,
              marginBottom: base * 0.025,
            }}
          >
            <svg
              width={base * 0.022}
              height={base * 0.022}
              viewBox="0 0 24 24"
              fill="none"
            >
              <rect
                x="3"
                y="5"
                width="18"
                height="16"
                rx="2"
                stroke={COLORS.orange}
                strokeWidth={2}
              />
              <line
                x1="3"
                y1="10"
                x2="21"
                y2="10"
                stroke={COLORS.orange}
                strokeWidth={2}
              />
              <line
                x1="8"
                y1="3"
                x2="8"
                y2="7"
                stroke={COLORS.orange}
                strokeWidth={2}
                strokeLinecap="round"
              />
              <line
                x1="16"
                y1="3"
                x2="16"
                y2="7"
                stroke={COLORS.orange}
                strokeWidth={2}
                strokeLinecap="round"
              />
            </svg>
            <div
              style={{
                fontFamily: FONT_MARKETING,
                fontWeight: 600,
                fontSize: base * 0.022,
                color: COLORS.text,
                letterSpacing: "-0.01em",
              }}
            >
              Week of Oct 14
            </div>
          </div>

          {/* 7 day cells */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(7, 1fr)",
              gap: base * 0.01,
            }}
          >
            {dayNames.map((day, i) => {
              const cellIn = staggeredSpring(
                frame,
                vfps,
                i,
                130,
                3,
                "ELASTIC"
              );
              return (
                <div
                  key={i}
                  style={{
                    background: "rgba(255,255,255,0.04)",
                    border: `1px solid ${COLORS.border}`,
                    borderRadius: base * 0.008,
                    padding: base * 0.014,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: base * 0.008,
                    aspectRatio: "0.85",
                    opacity: cellIn,
                    transform: `translateY(${interpolate(cellIn, [0, 1], [16, 0])}px) scale(${interpolate(cellIn, [0, 1], [0.9, 1])})`,
                  }}
                >
                  <div
                    style={{
                      fontFamily: FONT_PRIMARY,
                      fontSize: base * 0.011,
                      color: COLORS.textSubtle,
                      letterSpacing: "0.08em",
                      textTransform: "uppercase",
                    }}
                  >
                    {day}
                  </div>
                  <div
                    style={{
                      flex: 1,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <div
                      style={{
                        background: COLORS.card,
                        border: `1px solid ${COLORS.orange}`,
                        borderRadius: base * 0.006,
                        padding: `${base * 0.006}px ${base * 0.008}px`,
                        fontFamily: FONT_MONO,
                        fontSize: base * 0.014,
                        color: COLORS.orange,
                        fontWeight: 600,
                      }}
                    >
                      {zips[i]}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// =====================================================
// SCENE 5b (S5 in code): A system that runs itself
// Short scene: automation symbol
// =====================================================

export const fps = 25;
export const durationInFrames = 215;
export default Scene5Manual;
